1	"use client";
2	
3	import { useRef, useTransition } from "react";
4	import { useActionState } from "react";
5	import { replyTicket, setTicketStatus, setTicketPriority } from "@/lib/actions-support";
6	
7	export function ReplyForm({ ticketId }: { ticketId: string }) {
8	  const formRef = useRef<HTMLFormElement>(null);
9	  const [state, action, pending] = useActionState(
10	    async (prev: { error?: string }, fd: FormData) => {
11	      const res = await replyTicket(prev, fd);
12	      if (!res?.error) formRef.current?.reset();
13	      return res;
14	    },
15	    {} as { error?: string }
16	  );
17	  return (
18	    <form ref={formRef} action={action} className="space-y-3">
19	      <input type="hidden" name="ticketId" value={ticketId} />
20	      <textarea
21	        className="input min-h-28 resize-y"
22	        name="body"
23	        placeholder="Write a reply as staff…"
24	        required
25	        minLength={2}
26	      />
27	      <div className="flex items-center gap-3">
28	        <button className="btn-primary" disabled={pending}>
29	          {pending ? "Sending…" : "Send staff reply"}
30	        </button>
31	        {state?.error && <span className="text-xs text-red-400">{state.error}</span>}
32	      </div>
33	    </form>
34	  );
35	}
36	
37	export function PrioritySelect({ ticketId, priority }: { ticketId: string; priority: string }) {
38	  const [pending, start] = useTransition();
39	  return (
40	    <select
41	      className="input w-auto py-1.5 text-xs"
42	      defaultValue={priority}
43	      disabled={pending}
44	      onChange={(e) =>
45	        start(() => setTicketPriority(ticketId, e.target.value as "LOW" | "NORMAL" | "HIGH" | "URGENT"))
46	      }
47	    >
48	      <option value="LOW">Low</option>
49	      <option value="NORMAL">Normal</option>
50	      <option value="HIGH">High</option>
51	      <option value="URGENT">Urgent</option>
52	    </select>
53	  );
54	}
55	
56	export function TicketStatusButton({ ticketId, closed }: { ticketId: string; closed: boolean }) {
57	  const [pending, start] = useTransition();
58	  return (
59	    <button
60	      className={closed ? "btn-secondary py-1.5" : "btn-danger py-1.5"}
61	      disabled={pending}
62	      onClick={() => start(() => setTicketStatus(ticketId, closed ? "OPEN" : "CLOSED"))}
63	    >
64	      {closed ? "Reopen ticket" : "Close ticket"}
65	    </button>
66	  );
67	}
