1	import "server-only";
2	import { z } from "zod";
3	import { db } from "./db";
4	import { sendMail, emails } from "./mailer";
5	
6	/**
7	 * Shared reply-writing core for support tickets and live chat, extracted from
8	 * lib/actions-support.ts's `replyTicket` and lib/actions-chat.ts's
9	 * `replyToConversation` so there is exactly ONE code path that writes a
10	 * reply, regardless of which surface triggers it: the existing "use server"
11	 * actions behind /dashboard/support and /admin/chat, or the new Discord
12	 * bridge webhook (app/api/webhooks/discord/route.ts).
13	 *
14	 * SECURITY — READ THIS BEFORE CALLING EITHER FUNCTION BELOW.
15	 *
16	 * Neither function performs ANY authorization check. That is deliberate, not
17	 * an oversight: `lib/actions-support.ts`'s own top-of-file comment documents a
18	 * real, previously-shipped RBAC bug in this exact reply path (a SUPPORT agent
19	 * could silently neither answer nor close a ticket that wasn't their own), so
20	 * this extraction is surgical — the DB-write body moved here VERBATIM, auth
21	 * stayed put. Every existing caller still does its own guard before calling
22	 * in:
23	 *   - `replyTicket` (lib/actions-support.ts) calls `requireTicketActor()` first.
24	 *   - `replyToConversation`/`replyWithAttachment` (lib/actions-chat.ts) call
25	 *     `requireArea("support")` first.
26	 *   - The Discord webhook route's "auth" is Discord's own Ed25519
27	 *     interaction-signature verification (lib/discord.ts's
28	 *     `verifyDiscordSignature`) PLUS `lib/discord-bridge.ts`'s
29	 *     `resolveDiscordReplyActor`, which resolves the real Discord user who
30	 *     submitted the reply (via `interaction.member.user.id`) to a Nxeon
31	 *     `User.discordUserId` link and re-checks that account still has support
32	 *     access — see that file's top-of-file comment for the full design
33	 *     (real per-person linking via OAuth, no fallback to a single shared
34	 *     identity).
35	 *
36	 * Do NOT add a new caller of `writeTicketReply`/`writeChatReply` without first
37	 * adding its own auth check — these functions will happily write a reply
38	 * attributed to whatever actorId/staffId they're given.
39	 */
40	
41	/** Write a ticket reply. Mirrors `replyTicket`'s exact prior DB-write body. */
42	export async function writeTicketReply(args: {
43	  /** The id of the user the message is authored as (TicketMessage.authorId). */
44	  actorId: string;
45	  /** Whether the calling actor is support staff (before the same-ticket-owner override below). */
46	  actorIsSupportStaff: boolean;
47	  ticketId: string;
48	  body: string;
49	}): Promise<{ error?: string; isStaff?: boolean; ticketUserId?: string; subject?: string }> {
50	  const body = args.body.trim();
51	  if (body.length < 2 || body.length > 10000) return { error: "Message too short." };
52	
53	  const ticket = await db.ticket.findUnique({ where: { id: args.ticketId } });
54	  if (!ticket) return { error: "Ticket not found." };
55	  // A staff member replying to their OWN ticket (as its customer) is not a
56	  // "staff reply" — exactly the same override the original action applied.
57	  const isStaff = args.actorIsSupportStaff && ticket.userId !== args.actorId;
58	  if (ticket.userId !== args.actorId && !args.actorIsSupportStaff) return { error: "Forbidden." };
59	
60	  await db.$transaction([
61	    db.ticketMessage.create({ data: { ticketId: args.ticketId, body, authorId: args.actorId, isStaff } }),
62	    db.ticket.update({
63	      where: { id: args.ticketId },
64	      data: { status: isStaff ? "ANSWERED" : "CUSTOMER_REPLY" },
65	    }),
66	  ]);
67	
68	  if (isStaff) {
69	    await db.notification.create({
70	      data: {
71	        userId: ticket.userId,
72	        title: `Support replied: ${ticket.subject}`,
73	        href: `/dashboard/support/${args.ticketId}`,
74	      },
75	    });
76	    // Also EMAIL the customer the staff reply — an in-app bell alone is easy to
77	    // miss. Best-effort: a mail failure must never fail the reply itself.
78	    try {
79	      const customer = await db.user.findUnique({ where: { id: ticket.userId }, select: { email: true } });
80	      if (customer?.email) {
81	        const tpl = emails.ticketReply({
82	          ticketId: args.ticketId,
83	          subject: ticket.subject,
84	          replyPreview: body,
85	        });
86	        await sendMail({
87	          to: customer.email,
88	          subject: tpl.subject,
89	          html: tpl.html,
90	          template: tpl.template,
91	          userId: ticket.userId,
92	          kind: "support_reply",
93	        });
94	      }
95	    } catch (e) {
96	      console.error("[support] staff-reply email failed (non-fatal)", e);
97	    }
98	  } else {
99	    const admins = await db.user.findMany({ where: { role: "ADMIN" } });
100	    await db.notification.createMany({
101	      data: admins.map((a) => ({
102	        userId: a.id,
103	        title: `Ticket reply: ${ticket.subject}`,
104	        href: `/admin/support/${args.ticketId}`,
105	      })),
106	    });
107	  }
108	
109	  return { isStaff, ticketUserId: ticket.userId, subject: ticket.subject };
110	}
111	
112	/** Write a chat reply. Mirrors `replyToConversation`'s exact prior DB-write body. */
113	export async function writeChatReply(args: {
114	  conversationId: string;
115	  body: string;
116	  /** The staff/admin user id the reply is attributed to (assignedToId). */
117	  staffId: string;
118	}): Promise<{ error?: string; ok?: boolean; conversationUserId?: string | null }> {
119	  const parsed = z
120	    .object({ id: z.string().min(1), body: z.string().trim().min(1).max(5000) })
121	    .safeParse({ id: args.conversationId, body: args.body });
122	  if (!parsed.success) return { error: "Message must be between 1 and 5000 characters." };
123	
124	  const convo = await db.chatConversation.findUnique({ where: { id: parsed.data.id } });
125	  if (!convo) return { error: "Conversation not found." };
126	
127	  await db.$transaction([
128	    db.chatMessage.create({
129	      data: { conversationId: parsed.data.id, sender: "agent", body: parsed.data.body },
130	    }),
131	    db.chatConversation.update({
132	      where: { id: parsed.data.id },
133	      data: {
134	        status: "OPEN",
135	        unreadForUser: true,
136	        unreadForAgent: false,
137	        assignedToId: args.staffId,
138	        lastMessageAt: new Date(),
139	      },
140	    }),
141	  ]);
142	
143	  // If the visitor is a signed-in customer, drop them a notification.
144	  if (convo.userId) {
145	    await db.notification
146	      .create({
147	        data: {
148	          userId: convo.userId,
149	          title: "New reply in your live chat",
150	          href: "/dashboard",
151	        },
152	      })
153	      .catch(() => {});
154	  }
155	
156	  return { ok: true, conversationUserId: convo.userId };
157	}
