1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { redirect } from "next/navigation";
5	import { z } from "zod";
6	import { db } from "./db";
7	import { requireUser } from "./auth";
8	import { canAccess } from "./rbac";
9	import { writeTicketReply } from "./reply-core";
10	import { mirrorNewTicketToDiscord, mirrorTicketReplyToDiscord } from "./discord-bridge";
11	
12	/**
13	 * SUPPORT-ROLE ENFORCEMENT (2026-07-27 admin audit).
14	 *
15	 * `lib/rbac.ts` grants the `support` area to SUPPORT and ADMIN, `/admin/support`
16	 * and `/admin/support/[id]` both gate on `requireArea("support")`, and the admin
17	 * layout renders the desk in a SUPPORT agent's sidebar. Every WRITE behind those
18	 * pages, however, still required ADMIN:
19	 *
20	 *   - `setTicketPriority` called `requireAdmin()`. `PrioritySelect` does not
21	 *     catch, so a SUPPORT agent picked "Urgent", the throw vanished into an
22	 *     unhandled transition, and the `<select>` (uncontrolled, `defaultValue`)
23	 *     kept showing the new value. The control reported success and did nothing.
24	 *   - `setTicketStatus` and `replyTicket` applied the CUSTOMER ownership test
25	 *     (`ticket.userId !== user.id && role !== "ADMIN"`), so a SUPPORT agent could
26	 *     neither close nor answer a ticket that was not their own — i.e. any ticket.
27	 *
28	 * So the entire job of the SUPPORT role was a read-only page with three controls
29	 * that silently refused. `lib/actions-chat.ts` — the other half of the same area —
30	 * has always gated correctly on `requireArea("support")`; the ticket desk simply
31	 * was never updated when RBAC landed. These now use the same rule. No role gains
32	 * anything `lib/rbac.ts` did not already declare, and CUSTOMER is unaffected:
33	 * a customer still reaches only their own ticket.
34	 */
35	/**
36	 * The session behind a ticket action, plus whether they are support staff.
37	 *
38	 * Named `require*` deliberately. `test/auth-lockouts.test.ts` enforces that every
39	 * export of a "use server" file — each of which is a network-callable endpoint
40	 * anyone can POST to — calls a recognised guard INSIDE the function, and it
41	 * recognises guards by the `require*`/`owned*`/`assert*`/`resolve*` convention.
42	 * This helper was `ticketActor`, which guarded correctly but did not LOOK like a
43	 * guard, so the tripwire reported three genuinely-safe endpoints as unguarded.
44	 *
45	 * The fix was the name, not the rule: widening the rule to accept arbitrary
46	 * helper names would let a future function that guards nothing pass the same
47	 * check. A guard should be recognisable as one.
48	 */
49	async function requireTicketActor(): Promise<{ id: string; isSupportStaff: boolean }> {
50	  const user = await requireUser();
51	  return { id: user.id, isSupportStaff: canAccess(user.role, "support") };
52	}
53	
54	export async function createTicket(prev: any, formData: FormData): Promise<{ error?: string }> {
55	  const user = await requireUser();
56	  const parsed = z
57	    .object({
58	      subject: z.string().min(3).max(150),
59	      body: z.string().min(5).max(10000),
60	      priority: z.enum(["LOW", "NORMAL", "HIGH", "URGENT"]).default("NORMAL"),
61	    })
62	    .safeParse({
63	      subject: formData.get("subject"),
64	      body: formData.get("body"),
65	      priority: formData.get("priority") ?? "NORMAL",
66	    });
67	  if (!parsed.success) return { error: "Subject (3+) and message (5+) required." };
68	
69	  const ticket = await db.ticket.create({
70	    data: {
71	      subject: parsed.data.subject,
72	      priority: parsed.data.priority,
73	      userId: user.id,
74	      messages: { create: { body: parsed.data.body, authorId: user.id, isStaff: false } },
75	    },
76	  });
77	  const admins = await db.user.findMany({ where: { role: "ADMIN" } });
78	  await db.notification.createMany({
79	    data: admins.map((a) => ({
80	      userId: a.id,
81	      title: `New ticket: ${parsed.data.subject}`,
82	      href: `/admin/support/${ticket.id}`,
83	    })),
84	  });
85	  // Discord bridge (Phase 1 mirror): best-effort, never blocks ticket creation
86	  // or the redirect below — see lib/discord-bridge.ts's top-of-file comment.
87	  await mirrorNewTicketToDiscord(ticket.id);
88	  redirect(`/dashboard/support/${ticket.id}`);
89	}
90	
91	export async function replyTicket(prev: any, formData: FormData): Promise<{ error?: string }> {
92	  const user = await requireTicketActor();
93	  const ticketId = String(formData.get("ticketId") ?? "");
94	  const body = String(formData.get("body") ?? "").trim();
95	
96	  // Ownership guard, kept directly in this "use server" boundary — every
97	  // export of this file is a public network endpoint (see this file's
98	  // top-of-file comment on the exact RBAC bug that made that non-obvious).
99	  // `writeTicketReply` (lib/reply-core.ts) re-checks this same thing before
100	  // writing, so this is deliberate defense-in-depth, not the only place it's
101	  // enforced — but a reviewer of THIS file should still see proof a customer
102	  // can only reply to their own ticket without having to trust an opaque
103	  // helper elsewhere.
104	  const ticketOwner = await db.ticket.findUnique({ where: { id: ticketId }, select: { userId: true } });
105	  if (!ticketOwner) return { error: "Ticket not found." };
106	  if (ticketOwner.userId !== user.id && !user.isSupportStaff) return { error: "Forbidden." };
107	
108	  const result = await writeTicketReply({
109	    actorId: user.id,
110	    actorIsSupportStaff: user.isSupportStaff,
111	    ticketId,
112	    body,
113	  });
114	  if (result.error) return { error: result.error };
115	
116	  // Discord bridge (Phase 1 mirror): best-effort. This reply was written from
117	  // the web dashboard, never from Discord (Discord-originated replies go
118	  // through app/api/webhooks/discord/route.ts, which calls writeTicketReply
119	  // directly and does NOT mirror — otherwise a Discord reply would echo right
120	  // back into the same Discord thread it came from).
121	  await mirrorTicketReplyToDiscord(ticketId, body, Boolean(result.isStaff));
122	
123	  revalidatePath(`/dashboard/support/${ticketId}`);
124	  revalidatePath(`/admin/support/${ticketId}`);
125	  return {};
126	}
127	
128	/**
129	 * A TypeScript parameter type is a compile-time comment on a network endpoint.
130	 *
131	 * Every export of this file is POST-able with any JSON the caller likes, so the
132	 * `"OPEN" | "CLOSED"` annotations below constrained the components and nothing
133	 * else. `TicketStatus` also contains ANSWERED and CUSTOMER_REPLY — both writable
134	 * here — so a customer could stamp their own ticket ANSWERED and drop it out of
135	 * the support queue's "needs a reply" view without anyone having replied. Values
136	 * outside the enum reached Prisma and threw, which surfaces as a server error
137	 * page rather than a message. Both are fixed by validating at the boundary.
138	 */
139	const TICKET_STATUS_CHOICES = ["OPEN", "CLOSED"] as const;
140	const TICKET_PRIORITY_CHOICES = ["LOW", "NORMAL", "HIGH", "URGENT"] as const;
141	
142	export async function setTicketStatus(ticketId: string, status: "OPEN" | "CLOSED") {
143	  const user = await requireTicketActor();
144	  if (!TICKET_STATUS_CHOICES.includes(status as (typeof TICKET_STATUS_CHOICES)[number])) {
145	    throw new Error("A ticket can only be reopened or closed from here.");
146	  }
147	  const ticket = await db.ticket.findUnique({ where: { id: ticketId } });
148	  if (!ticket) throw new Error("Not found");
149	  if (ticket.userId !== user.id && !user.isSupportStaff) throw new Error("Forbidden");
150	  await db.ticket.update({ where: { id: ticketId }, data: { status } });
151	  revalidatePath(`/dashboard/support`);
152	  revalidatePath(`/dashboard/support/${ticketId}`);
153	  revalidatePath(`/admin/support`);
154	  revalidatePath(`/admin/support/${ticketId}`);
155	}
156	
157	export async function setTicketPriority(ticketId: string, priority: "LOW" | "NORMAL" | "HIGH" | "URGENT") {
158	  const user = await requireTicketActor();
159	  // Triage is a staff-only judgement — a customer must not be able to promote
160	  // their own ticket to URGENT — but it IS the support desk's job.
161	  if (!user.isSupportStaff) throw new Error("Forbidden");
162	  if (!TICKET_PRIORITY_CHOICES.includes(priority as (typeof TICKET_PRIORITY_CHOICES)[number])) {
163	    throw new Error("Priority must be one of: LOW, NORMAL, HIGH, URGENT.");
164	  }
165	  await db.ticket.update({ where: { id: ticketId }, data: { priority } });
166	  revalidatePath(`/admin/support`);
167	  revalidatePath(`/admin/support/${ticketId}`);
168	}
