23	    size = (await fs.stat(path)).size;
24	  } catch {
25	    return new NextResponse("Missing", { status: 404 });
26	  }
27	
28	  const range = req.headers.get("range");
29	  const disposition = att.kind === "FILE" ? `attachment; filename="${att.filename.replace(/"/g, "")}"` : "inline";
30	  // Never let an inline-served attachment execute as a document: `nosniff` stops
31	  // MIME-sniffing an image into HTML, and `default-src 'none'; sandbox` neuters
32	  // any script even in a legacy SVG that predates the upload-side reject.
33	  const baseHeaders: Record<string, string> = {
34	    "Content-Type": att.mime,
35	    "Content-Disposition": disposition,
36	    "Accept-Ranges": "bytes",
37	    "X-Content-Type-Options": "nosniff",
38	    "Content-Security-Policy": "default-src 'none'; sandbox",
39	  };
40	
41	  if (range) {
42	    const m = /bytes=(\d+)-(\d*)/.exec(range);
43	    if (m) {
44	      const start = Number(m[1]);
45	      const end = m[2] ? Math.min(Number(m[2]), size - 1) : size - 1;
46	      if (start <= end && start < size) {
47	        const stream = createReadStream(path, { start, end });
48	        return new NextResponse(Readable.toWeb(stream) as unknown as ReadableStream, {
49	          status: 206,
50	          headers: { ...baseHeaders, "Content-Range": `bytes ${start}-${end}/${size}`, "Content-Length": String(end - start + 1) },
51	        });
52	      }
53	    }
54	  }
55	  const stream = createReadStream(path);
56	  return new NextResponse(Readable.toWeb(stream) as unknown as ReadableStream, {
57	    status: 200,
58	    headers: { ...baseHeaders, "Content-Length": String(size) },
59	  });
60	}
