/**
 * Security core for support-ticket attachments.
 *
 * Mirrors lib/chat-attachment.ts's shape and guarantees (bytes validated by
 * *signature*, not the client-declared Content-Type; SVG never allowed) but
 * widens the allow-list beyond images: a ticket reply can also carry a PDF,
 * a plain-text/log file, or a ZIP — the file-upload button says "attach a
 * file", not "attach an image", so the validator has to mean that.
 *
 * Images are re-validated with lib/chat-attachment.ts's own sniffer rather
 * than a second copy of the magic-number table, so the two allow-lists can
 * never drift apart on what counts as a real PNG/JPEG/GIF/WEBP.
 */
import {
  ALLOWED_IMAGE_MIME,
  isAllowedImageMime,
  sniffImageMime,
  type AllowedImageMime,
} from "./chat-attachment";

/** Non-image document types a ticket attachment may declare. */
export const ALLOWED_DOC_MIME = [
  "application/pdf",
  "text/plain",
  "application/zip",
  "application/x-zip-compressed",
] as const;
export type AllowedDocMime = (typeof ALLOWED_DOC_MIME)[number];

/** `accept` attribute for the ticket file input: images + the document types above. */
export const TICKET_ACCEPT_ATTR = [
  ...ALLOWED_IMAGE_MIME,
  "application/pdf",
  ".pdf",
  "text/plain",
  ".txt",
  ".log",
  "application/zip",
  ".zip",
].join(",");

/**
 * Hard cap: 10 MB. A support attachment (log dump, screenshot, small PDF) runs
 * larger than a chat image; still well short of anything that would strain
 * storing bytes in Postgres. Enforced server-side regardless of any client check.
 */
export const MAX_TICKET_ATTACHMENT_BYTES = 10 * 1024 * 1024;

export type TicketAttachmentValidation =
  | { ok: true; mime: string; bytes: Buffer }
  | { ok: false; error: string };

function sniffPdf(buf: Buffer): boolean {
  // "%PDF"
  return buf.length >= 4 && buf[0] === 0x25 && buf[1] === 0x50 && buf[2] === 0x44 && buf[3] === 0x46;
}

function sniffZip(buf: Buffer): boolean {
  if (buf.length < 4) return false;
  // Local file header "PK\x03\x04", empty archive "PK\x05\x06", spanned "PK\x07\x08".
  if (buf[0] !== 0x50 || buf[1] !== 0x4b) return false;
  return (
    (buf[2] === 0x03 && buf[3] === 0x04) ||
    (buf[2] === 0x05 && buf[3] === 0x06) ||
    (buf[2] === 0x07 && buf[3] === 0x08)
  );
}

/**
 * Plain text/log has no magic number. Instead of trusting the extension alone,
 * reject anything that looks binary — a NUL byte, or a high proportion of
 * non-printable bytes, in the first 8 KB — the same heuristic tools like git
 * use to tell text from binary. This does not "validate" the content, it just
 * keeps an executable or image mislabeled as .txt from being accepted as one.
 */
function looksLikeText(buf: Buffer): boolean {
  const sample = buf.subarray(0, 8192);
  if (sample.length === 0) return true;
  let suspicious = 0;
  for (let i = 0; i < sample.length; i++) {
    const b = sample[i];
    if (b === 0) return false; // NUL byte: never text
    // Allow common whitespace control chars; count everything else below 0x20 as suspicious.
    if (b < 0x09 || (b > 0x0d && b < 0x20)) suspicious++;
  }
  return suspicious / sample.length < 0.05;
}

function extOf(filename: string | null | undefined): string {
  return (filename ?? "").toLowerCase().match(/\.[a-z0-9]{1,8}$/)?.[0] ?? "";
}

/**
 * Full server-side validation of a ticket attachment (image OR document).
 * Enforces, in order: non-empty, size ≤ cap, then dispatches to the right
 * signature check based on what the bytes actually look like — the declared
 * MIME/filename are only ever used to pick which check to try first, never
 * trusted on their own.
 */
export function validateTicketAttachmentBytes(
  bytes: Buffer | Uint8Array,
  declaredMime?: string | null,
  filename?: string | null
): TicketAttachmentValidation {
  const buf = Buffer.isBuffer(bytes) ? bytes : Buffer.from(bytes);

  if (buf.length === 0) return { ok: false, error: "Empty file." };
  if (buf.length > MAX_TICKET_ATTACHMENT_BYTES) {
    return { ok: false, error: "File is larger than 10 MB." };
  }

  const declared = (declaredMime ?? "").split(";")[0]?.trim().toLowerCase() || null;
  if (declared === "image/svg+xml") {
    return { ok: false, error: "SVG images are not allowed." };
  }

  // 1. Image — delegate to the shared image sniffer/allow-list.
  const sniffedImage = sniffImageMime(buf);
  if (sniffedImage) {
    if (declared && isAllowedImageMime(declared) && declared !== sniffedImage) {
      return { ok: false, error: "Image contents do not match its declared type." };
    }
    return { ok: true, mime: sniffedImage, bytes: buf };
  }
  if (declared && isAllowedImageMime(declared)) {
    // Claimed to be an allow-listed image but failed the byte signature check.
    return { ok: false, error: "File is not a supported image (PNG, JPEG, GIF, or WEBP)." };
  }

  // 2. PDF
  if (sniffPdf(buf)) return { ok: true, mime: "application/pdf", bytes: buf };
  if (declared === "application/pdf") {
    return { ok: false, error: "File is not a valid PDF." };
  }

  // 3. ZIP
  if (sniffZip(buf)) return { ok: true, mime: "application/zip", bytes: buf };
  if (declared === "application/zip" || declared === "application/x-zip-compressed") {
    return { ok: false, error: "File is not a valid ZIP archive." };
  }

  // 4. Plain text / log — no magic number, so lean on extension + a binary-content check.
  const ext = extOf(filename);
  const looksLikeTextFile = declared === "text/plain" || ext === ".txt" || ext === ".log";
  if (looksLikeTextFile) {
    if (!looksLikeText(buf)) {
      return { ok: false, error: "File does not look like a plain-text/log file." };
    }
    return { ok: true, mime: "text/plain", bytes: buf };
  }

  return {
    ok: false,
    error: "Unsupported file type. Allowed: images, PDF, TXT, LOG, or ZIP.",
  };
}

export function isImageMime(mime: string): mime is AllowedImageMime {
  return isAllowedImageMime(mime);
}

