/** Write a ticket reply. Mirrors `replyTicket`'s exact prior DB-write body. */
export async function writeTicketReply(args: {
  /** The id of the user the message is authored as (TicketMessage.authorId). */
  actorId: string;
  /** Whether the calling actor is support staff (before the same-ticket-owner override below). */
  actorIsSupportStaff: boolean;
  ticketId: string;
  body: string;
  /** Optional single attachment (image or document) — see lib/ticket-attachment.ts. */
  attachment?: { mime: string; name: string; size: number; data: Buffer };
}): Promise<{ error?: string; isStaff?: boolean; ticketUserId?: string; subject?: string }> {
  const body = args.body.trim();
  // A message with an attachment and no caption is allowed (mirrors the chat
  // widget's image-only messages), so the length floor only applies when there
  // is no attachment to carry the message on its own.
  if (!args.attachment && (body.length < 2 || body.length > 10000)) return { error: "Message too short." };
  if (body.length > 10000) return { error: "Message is too long." };

  const ticket = await db.ticket.findUnique({ where: { id: args.ticketId } });
  if (!ticket) return { error: "Ticket not found." };
  // A staff member replying to their OWN ticket (as its customer) is not a
  // "staff reply" — exactly the same override the original action applied.
  const isStaff = args.actorIsSupportStaff && ticket.userId !== args.actorId;
  if (ticket.userId !== args.actorId && !args.actorIsSupportStaff) return { error: "Forbidden." };

  await db.$transaction([
    db.ticketMessage.create({
      data: {
        ticketId: args.ticketId,
        body,
        authorId: args.actorId,
        isStaff,
        ...(args.attachment
          ? {
              attachmentData: args.attachment.data,
              attachmentMime: args.attachment.mime,
              attachmentName: args.attachment.name,
              attachmentSize: args.attachment.size,
            }
          : {}),
      },
    }),
    db.ticket.update({
      where: { id: args.ticketId },
      data: { status: isStaff ? "ANSWERED" : "CUSTOMER_REPLY" },
    }),
  ]);

