  const ticketId = String(formData.get("ticketId") ?? "");
  const body = String(formData.get("body") ?? "").trim();

  // Ownership guard, kept directly in this "use server" boundary — every
  // export of this file is a public network endpoint (see this file's
  // top-of-file comment on the exact RBAC bug that made that non-obvious).
  // `writeTicketReply` (lib/reply-core.ts) re-checks this same thing before
  // writing, so this is deliberate defense-in-depth, not the only place it's
  // enforced — but a reviewer of THIS file should still see proof a customer
  // can only reply to their own ticket without having to trust an opaque
  // helper elsewhere.
  const ticketOwner = await db.ticket.findUnique({ where: { id: ticketId }, select: { userId: true } });
  if (!ticketOwner) return { error: "Ticket not found." };
  if (ticketOwner.userId !== user.id && !user.isSupportStaff) return { error: "Forbidden." };

  // Optional single attachment (paste-image or file-picker upload). The same
  // ownership guard above already covers who may attach — a customer can only
  // ever reach here for their own ticket, staff for any ticket they can open.
  let attachment: { mime: string; name: string; size: number; data: Buffer } | undefined;
  const file = formData.get("file");
  if (file instanceof File && file.size > 0) {
    if (file.size > MAX_TICKET_ATTACHMENT_BYTES) {
      return { error: "File is larger than 10 MB." };
    }
    const bytes = Buffer.from(await file.arrayBuffer());
    const check = validateTicketAttachmentBytes(bytes, file.type, file.name);
    if (!check.ok) return { error: check.error };
    attachment = { mime: check.mime, name: file.name.slice(0, 200) || "attachment", size: check.bytes.length, data: check.bytes };
  }

  const result = await writeTicketReply({
    actorId: user.id,
    actorIsSupportStaff: user.isSupportStaff,
    ticketId,
    body,
    attachment,
  });
  if (result.error) return { error: result.error };

