/** How long after sending a message its author may still edit it. */
const EDIT_WINDOW_MS = 5 * 60_000;

/**
 * Edit the body of your own message, within 5 minutes of sending it, while the
 * ticket is open. The 5-minute window is enforced HERE against `createdAt` —
 * never trust a client-side countdown, which only controls whether the "Edit"
 * affordance is shown. `editedAt` is set so both the admin and customer UI can
 * render an "(edited)" label — an edit is a transparency signal both parties
 * see, unlike the read receipts below which are staff-facing only.
 */
export async function editTicketMessage(messageId: string, newBody: string): Promise<{ error?: string }> {
  const user = await requireUser();
  const body = newBody.trim();
  if (body.length < 2 || body.length > 10000) return { error: "Message must be between 2 and 10,000 characters." };

  const message = await db.ticketMessage.findUnique({
    where: { id: messageId },
    include: { ticket: { select: { id: true, status: true } } },
  });
  if (!message) return { error: "Message not found." };
  if (message.authorId !== user.id) return { error: "You can only edit your own messages." };
  if (message.ticket.status === "CLOSED") return { error: "This ticket is closed." };
  if (Date.now() - message.createdAt.getTime() >= EDIT_WINDOW_MS) {
    return { error: "You can only edit a message within 5 minutes of sending it." };
  }

  await db.ticketMessage.update({ where: { id: messageId }, data: { body, editedAt: new Date() } });
  revalidatePath(`/dashboard/support/${message.ticket.id}`);
  revalidatePath(`/admin/support/${message.ticket.id}`);
  return {};
}

/**
 * Stamp `readAt` on every unread STAFF message in this ticket — called once
 * from app/dashboard/support/[id]/page.tsx when the CUSTOMER who owns the
 * ticket views it. Deliberately one-directional: there is no equivalent call
 * for staff viewing a customer's messages, per the explicit design ("read
 * receipts from customers, but they dont get them from us") — staff sees when
 * the customer has read a staff reply; the customer never sees a receipt at all.
 */
export async function markTicketMessagesRead(ticketId: string): Promise<void> {
  const user = await requireUser();
  const ticket = await db.ticket.findUnique({ where: { id: ticketId }, select: { userId: true } });
  if (!ticket || ticket.userId !== user.id) return; // silently a no-op for anyone but the owning customer
  await db.ticketMessage.updateMany({
    where: { ticketId, isStaff: true, readAt: null },
    data: { readAt: new Date() },
  });
}

